#!/usr/bin/env python3
"""Cross-check main and forensic canonical payment outputs and monthly cash totals."""
from pathlib import Path
import pandas as pd
import numpy as np
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'data/processed'; REPORTS=ROOT/'reports'
main=pd.read_csv(OUT/'payments_canonical.csv')
forensic=pd.read_csv(OUT/'payments_canonical_forensic.csv')
monthly=pd.read_csv(OUT/'monthly_recovery_metrics.csv')
checks=[
 {'check_id':'RECON-001','measure':'Main vs forensic canonical event count','main_value':len(main),'forensic_value':len(forensic),'absolute_difference':abs(len(main)-len(forensic)),'tolerance':0,'status':'PASS' if len(main)==len(forensic) else 'FAIL'},
 {'check_id':'RECON-002','measure':'Main vs forensic effective recovered cash (INR)','main_value':float(main.effective_recovered_amount.sum()),'forensic_value':float(forensic.effective_amount.sum()),'absolute_difference':abs(float(main.effective_recovered_amount.sum())-float(forensic.effective_amount.sum())),'tolerance':0.01,'status':'PASS' if np.isclose(main.effective_recovered_amount.sum(),forensic.effective_amount.sum(),atol=0.01) else 'FAIL'},
 {'check_id':'RECON-003','measure':'Canonical cash vs monthly metrics total (INR)','main_value':float(main.effective_recovered_amount.sum()),'forensic_value':float(monthly.recovered_amount.sum()),'absolute_difference':abs(float(main.effective_recovered_amount.sum())-float(monthly.recovered_amount.sum())),'tolerance':0.01,'status':'PASS' if np.isclose(main.effective_recovered_amount.sum(),monthly.recovered_amount.sum(),atol=0.01) else 'FAIL'},
]
df=pd.DataFrame(checks); df.to_csv(OUT/'cross_output_reconciliation.csv',index=False)
# Update acceptance inventory with observed cross-output results.
path=OUT/'data_quality_acceptance_checks.csv'; qa=pd.read_csv(path)
for c in checks:
    qa.loc[len(qa)]={'check_id':c['check_id'],'area':'cross_output_reconciliation','severity':'CRITICAL','check':c['measure'],'observed':c['absolute_difference'],'threshold':c['tolerance'],'status':c['status'],'business_impact':'Keeps canonical event count and cash totals consistent across reports','action':'Block release and investigate if failed'}
qa['observed']=qa['observed'].astype('object')
qa.loc[qa.check_id.eq('DQ-003'),'observed']=f"main={len(main)}; forensic={len(forensic)}"
qa.loc[qa.check_id.eq('DQ-003'),'threshold']='count and cash must reconcile'
qa.loc[qa.check_id.eq('DQ-003'),'status']='PASS' if all(c['status']=='PASS' for c in checks[:2]) else 'FAIL'
qa.to_csv(path,index=False)
status='PASS' if all(c['status']=='PASS' for c in checks) else 'FAIL'
REPORTS.joinpath('sql_python_reconciliation.md').write_text(f'''# Cross-output reconciliation\n\n**Status: {status}**\n\nGenerated by `python src/reconcile_outputs.py` after the canonical and forensic stages.\n\n| Check | Main output | Comparison output | Absolute difference | Tolerance | Status |\n|---|---:|---:|---:|---:|---|\n'''+''.join(f"| {r['measure']} | {r['main_value']:,.2f} | {r['forensic_value']:,.2f} | {r['absolute_difference']:,.2f} | {r['tolerance']:,.2f} | {r['status']} |\n" for r in checks)+'''\nThis is an internal Python-output consistency check, not a reconciliation to an external Finance ledger. SQL templates are not claimed to have run against PostgreSQL.\n''',encoding='utf-8')
if status!='PASS': raise SystemExit('Cross-output reconciliation failed; see data/processed/cross_output_reconciliation.csv')
print('Cross-output reconciliation passed: event counts and cash totals agree.')
